class Solution {
public:
    vector<int> killProcess(vector<int>& pid, vector<int>& ppid, int kill) {
        unordered_map<int, vector<int>> children;
        for (size_t i = 0; i < pid.size(); ++i) {
            children[ppid[i]].push_back(pid[i]);
        }
        vector<int> res;
        queue<int> q;
        q.push(kill);
        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            res.push_back(curr);
            if (children.count(curr)) {
                for (int child : children[curr]) {
                    q.push(child);
                }
            }
        }
        return res;
    }
};

class Solution {
    public List<Integer> killProcess(List<Integer> pid, List<Integer> ppid, int kill) {
        Map<Integer, List<Integer>> children = new HashMap<>();
        for (int i = 0; i < pid.size(); i++) {
            children.computeIfAbsent(ppid.get(i), k -> new ArrayList<>()).add(pid.get(i));
        }
        List<Integer> res = new ArrayList<>();
        Queue<Integer> q = new LinkedList<>();
        q.offer(kill);
        while (!q.isEmpty()) {
            int curr = q.poll();
            res.add(curr);
            if (children.containsKey(curr)) {
                q.addAll(children.get(curr));
            }
        }
        return res;
    }
}

/**
 * @param {number[]} pid
 * @param {number[]} ppid
 * @param {number} kill
 * @return {number[]}
 */
var killProcess = function(pid, ppid, kill) {
    const children = new Map();
    for (let i = 0; i < pid.length; i++) {
        if (!children.has(ppid[i])) children.set(ppid[i], []);
        children.get(ppid[i]).push(pid[i]);
    }
    const res = [];
    const q = [kill];
    while (q.length > 0) {
        const curr = q.shift();
        res.push(curr);
        if (children.has(curr)) {
            q.push(...children.get(curr));
        }
    }
    return res;
};
